// One player's build cursor. Follows the pointer from the input snapshot
// (works for remote peers too), snaps to the grid, shows whether the spot is
// valid and asks the GameManager to place a tower on "fire".
function distToPath(path, x, y) {
  let best = Infinity;
  for (let i = 0; i < path.length - 1; i++) {
    const ax = path[i][0], ay = path[i][1], bx = path[i + 1][0], by = path[i + 1][1];
    const dx = bx - ax, dy = by - ay;
    const len2 = dx * dx + dy * dy || 1;
    const t = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / len2));
    best = Math.min(best, Math.hypot(x - (ax + dx * t), y - (ay + dy * t)));
  }
  return best;
}

defineScript({
  name: 'Builder',
  description: 'Per-player tower placement cursor.',
  props: {
    color: { type: 'string', default: '#4cc2ff', label: 'Colour (hex)' },
    label: { type: 'string', default: 'P1' },
    cost: { type: 'integer', default: 50 },
  },
  onStart(ctx) {
    ctx.state.gold = 0;
    ctx.state.valid = false;
    const plate = ctx.world.getChildren(ctx.entity)[0];
    const text = plate !== undefined ? ctx.getOn(plate, 'Text') : null;
    if (text) { text.text = ctx.props.label; text.color.setHex(ctx.props.color); }
    ctx.send('queryGold', {});
  },
  onMessage(ctx, name, data) {
    if (name === 'goldChanged') ctx.state.gold = data.gold;
  },
  isLocal(ctx) {
    const pi = ctx.playerInput;
    return !!pi && (pi.owner === 'local' || pi.owner === ctx.net.localId);
  },
  /** Snap a world position to the build grid (1-unit cells centred on .5). */
  place(ctx, x, y) {
    const gx = Math.floor(x) + 0.5, gy = Math.floor(y) + 0.5;
    ctx.transform.setPosition(gx, gy);
    const gm = ctx.find('GameManager');
    const p = gm !== undefined ? ctx.getOn(gm, 'Script').props : null;
    let valid = !!p && Math.abs(gx) <= p.mapWidth / 2 - 0.5 && Math.abs(gy) <= p.mapHeight / 2 - 0.5 && distToPath(p.path, gx, gy) >= p.pathClearance;
    if (valid) for (const t of ctx.findAll('tower')) { const tt = ctx.getOn(t, 'Transform'); if (Math.abs(tt.x - gx) < 0.9 && Math.abs(tt.y - gy) < 0.9) { valid = false; break; } }
    ctx.state.valid = valid;
    const shape = ctx.get('Shape');
    if (shape) shape.stroke.setHex(!valid ? '#ef476f' : ctx.state.gold >= ctx.props.cost ? ctx.props.color : '#ffd166');
  },
  build(ctx) {
    if (ctx.state.valid) ctx.send('placeTower', { x: ctx.transform.x, y: ctx.transform.y, by: ctx.net.owner() });
  },
  onOwnerInput(ctx, snap) {
    if (snap.pointer) this.place(ctx, snap.pointer.x, snap.pointer.y);
    if (snap.pressed.includes('fire')) this.build(ctx);
  },
  onUpdate(ctx) {
    // Touch fallback for the local player: a tap aims and builds in one go
    // (a quick tap starts and ends between frames, so use the tap counter).
    if (!this.isLocal(ctx)) return;
    const touch = ctx.input.touch;
    if (touch.taps > 0) {
      const w = ctx.engine.screenToWorld(touch.lastPosition.x, touch.lastPosition.y);
      this.place(ctx, w.x, w.y);
      this.build(ctx);
    } else if (touch.touches.length > 0) {
      const p = touch.touches[0].position;
      const w = ctx.engine.screenToWorld(p.x, p.y);
      this.place(ctx, w.x, w.y);
    }
  },
});

// Walks the road defined by the GameManager's `path`; damaged by Shots.
defineScript({
  name: 'Enemy',
  description: 'Path-following creep with a health bar.',
  props: {
    speed: { type: 'number', default: 1.6, min: 0.1, max: 20 },
    hp: { type: 'integer', default: 3, min: 1 },
    reward: { type: 'integer', default: 8, min: 0 },
    big: { type: 'boolean', default: false },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.hp = ctx.props.hp;
    s.maxHp = ctx.props.hp;
    s.index = 1;
    s.dead = false;
    const gm = ctx.find('GameManager');
    s.path = gm !== undefined ? ctx.getOn(gm, 'Script').props.path : [[0, 0]];
    if (ctx.props.big) { const shape = ctx.get('Shape'); if (shape) { shape.radius = 0.55; shape.fill.setHex('#b23a5a'); } }
  },
  onFixedUpdate(ctx, dt) {
    const s = ctx.state;
    if (s.dead || s.index >= s.path.length) return;
    const t = ctx.transform;
    const [tx, ty] = s.path[s.index];
    const dx = tx - t.x, dy = ty - t.y;
    const d = Math.hypot(dx, dy);
    const step = ctx.props.speed * dt;
    if (d <= step) {
      t.setPosition(tx, ty);
      s.index++;
      if (s.index >= s.path.length && ctx.net.isHost) { s.dead = true; ctx.send('enemyReachedBase', {}); this.remove(ctx); }
    } else t.setPosition(t.x + (dx / d) * step, t.y + (dy / d) * step);
    // Wobble while walking.
    const shape = ctx.get('Shape');
    if (shape) shape.height = shape.width = 1 + Math.sin(ctx.time.elapsed * 12) * 0.06;
  },
  onMessage(ctx, name, data) {
    if (name !== 'damage' || ctx.state.dead || !ctx.net.isHost) return;
    ctx.state.hp -= data.amount;
    for (const child of ctx.world.getChildren(ctx.entity)) {
      if (ctx.nameOf(child) !== 'Health') continue;
      const bar = ctx.getOn(child, 'Shape');
      bar.width = 0.8 * Math.max(0, ctx.state.hp / ctx.state.maxHp);
      bar.fill.setHex(ctx.state.hp / ctx.state.maxHp > 0.5 ? '#06d6a0' : '#ffd166');
    }
    if (ctx.state.hp > 0) return;
    ctx.state.dead = true;
    ctx.audio.play('hit', { volume: 0.35, pitchVariation: 0.2 });
    const em = ctx.get('ParticleEmitter');
    if (em) em.burst(ctx.props.big ? 30 : 14);
    const shape = ctx.get('Shape');
    if (shape) shape.visible = false;
    for (const child of ctx.world.getChildren(ctx.entity)) { const cs = ctx.getOn(child, 'Shape'); if (cs) cs.visible = false; }
    ctx.send('enemyKilled', { reward: ctx.props.reward });
    ctx.timer(0.5, () => this.remove(ctx));
  },
  remove(ctx) {
    const sync = ctx.net.hub.sync;
    if (sync && ctx.net.isHost) sync.despawn(ctx.entity); else ctx.destroy();
  },
});

// Shared tower-defence state: gold, base health, waves, tower placement.
// Every player gets a Builder cursor; placement requests arrive as messages
// and are validated here on the host, so the whole team spends one purse.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }

const COLORS = ['#4cc2ff', '#ff7a3d', '#8b7dff', '#06d6a0'];

function distToPath(path, x, y) {
  let best = Infinity;
  for (let i = 0; i < path.length - 1; i++) {
    const ax = path[i][0], ay = path[i][1], bx = path[i + 1][0], by = path[i + 1][1];
    const dx = bx - ax, dy = by - ay;
    const len2 = dx * dx + dy * dy || 1;
    const t = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / len2));
    best = Math.min(best, Math.hypot(x - (ax + dx * t), y - (ay + dy * t)));
  }
  return best;
}

defineScript({
  name: 'GameManager',
  description: 'Gold, waves, base health and tower placement.',
  props: {
    startGold: { type: 'integer', default: 120, min: 0 },
    towerCost: { type: 'integer', default: 50, min: 1 },
    baseHealth: { type: 'integer', default: 20, min: 1 },
    waveDelay: { type: 'number', default: 5, min: 0, max: 60, label: 'Seconds between waves' },
    waveBonus: { type: 'integer', default: 25 },
    mapWidth: { type: 'number', default: 36 },
    mapHeight: { type: 'number', default: 18 },
    pathClearance: { type: 'number', default: 1.1, label: 'Min distance from the road' },
    path: { type: 'json', default: [[-16, 6], [-8, 6], [-8, -4], [2, -4], [2, 5], [10, 5], [10, -3], [16.5, -3]] },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.gold = ctx.props.startGold;
    s.base = ctx.props.baseHealth;
    s.wave = 0;
    s.toSpawn = 0;
    s.over = false;
    s.players = {};
    s.count = 0;
    s.unsub = [];
    if (ctx.net.isHost) {
      this.addPlayer(ctx, ctx.net.localId);
      const sync = ctx.net.hub.sync;
      if (sync) {
        for (const p of sync.players()) if (p.peerId !== ctx.net.localId) this.addPlayer(ctx, p.peerId);
        s.unsub.push(sync.on('playerJoined', ({ peerId }) => this.addPlayer(ctx, peerId)));
        s.unsub.push(sync.on('playerLeft', ({ peerId }) => this.removePlayer(ctx, peerId)));
      }
      s.nextWaveAt = ctx.time.elapsed + ctx.props.waveDelay;
    }
    this.drawHud(ctx);
  },
  onDestroy(ctx) {
    for (const off of ctx.state.unsub) off();
    const h = hud(ctx);
    if (h) { h.remove('gold'); h.remove('wave'); h.remove('hint'); h.remove('over'); }
  },
  addPlayer(ctx, peerId) {
    const s = ctx.state;
    if (s.players[peerId]) return;
    const index = s.count++;
    const entity = ctx.net.spawn('Builder', { ownerId: peerId, position: { x: 0, y: 0 } });
    const pi = ctx.getOn(entity, 'PlayerInput');
    if (pi) pi.owner = peerId;
    const ni = ctx.getOn(entity, 'NetworkIdentity');
    if (ni) ni.ownerId = peerId;
    const name = ctx.getOn(entity, 'Name');
    if (name) name.name = `Builder ${peerId}`;
    const script = ctx.getOn(entity, 'Script');
    script.props.color = COLORS[index % COLORS.length];
    script.props.label = `P${index + 1}`;
    script.props.cost = ctx.props.towerCost;
    s.players[peerId] = { entity, index };
  },
  removePlayer(ctx, peerId) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    if (ctx.world.isAlive(p.entity)) {
      const sync = ctx.net.hub.sync;
      if (sync) sync.despawn(p.entity); else ctx.destroy(p.entity);
    }
    delete ctx.state.players[peerId];
  },

  canPlace(ctx, x, y) {
    const hw = ctx.props.mapWidth / 2, hh = ctx.props.mapHeight / 2;
    if (Math.abs(x) > hw - 0.5 || Math.abs(y) > hh - 0.5) return false;
    if (distToPath(ctx.props.path, x, y) < ctx.props.pathClearance) return false;
    for (const t of ctx.findAll('tower')) {
      const tt = ctx.getOn(t, 'Transform');
      if (Math.abs(tt.x - x) < 0.9 && Math.abs(tt.y - y) < 0.9) return false;
    }
    return true;
  },
  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (name === 'queryGold') { ctx.send('goldChanged', { gold: s.gold }); return; }
    if (!ctx.net.isHost || s.over) return;
    if (name === 'placeTower') {
      if (s.gold < ctx.props.towerCost || !this.canPlace(ctx, data.x, data.y)) { ctx.audio.play('deny', { volume: 0.4 }); return; }
      s.gold -= ctx.props.towerCost;
      const tower = ctx.net.spawn('Tower', { position: { x: data.x, y: data.y } });
      ctx.getOn(tower, 'Script').props.builtBy = data.by || '';
      ctx.audio.play('place', { volume: 0.6 });
      ctx.send('goldChanged', { gold: s.gold });
    } else if (name === 'enemyKilled') {
      s.gold += data.reward || 0;
      ctx.send('goldChanged', { gold: s.gold });
    } else if (name === 'enemyReachedBase') {
      s.base--;
      ctx.audio.play('lose', { volume: 0.7 });
      const cam = ctx.find('Camera');
      const c = cam !== undefined ? ctx.getOn(cam, 'Camera2D') : null;
      if (c) c.shake = 0.3;
      if (s.base <= 0) this.gameOver(ctx);
    }
    this.drawHud(ctx);
  },
  onUpdate(ctx) {
    const s = ctx.state;
    if (!ctx.net.isHost || s.over) return;
    if (s.nextWaveAt !== undefined && ctx.time.elapsed >= s.nextWaveAt) { s.nextWaveAt = undefined; this.startWave(ctx); }
    if (s.nextWaveAt === undefined && s.toSpawn === 0 && s.wave > 0 && ctx.findAll('enemy').length === 0 && !s.cleared) {
      s.cleared = true;
      s.gold += ctx.props.waveBonus;
      ctx.audio.play('clear', { volume: 0.6 });
      ctx.send('goldChanged', { gold: s.gold });
      s.nextWaveAt = ctx.time.elapsed + ctx.props.waveDelay;
    }
    if (ctx.time.frame % 10 === 0) this.drawHud(ctx);
  },
  startWave(ctx) {
    const s = ctx.state;
    s.wave++;
    s.cleared = false;
    s.toSpawn = 4 + s.wave * 2;
    const hp = 2 + Math.floor(s.wave * 1.3);
    const speed = 1.6 + s.wave * 0.1;
    const start = ctx.props.path[0];
    const spawnOne = () => {
      if (s.over || s.toSpawn <= 0) return;
      s.toSpawn--;
      const e = ctx.net.spawn('Enemy', { position: { x: start[0], y: start[1] } });
      const sc = ctx.getOn(e, 'Script');
      sc.props.hp = hp;
      sc.props.speed = speed;
      sc.props.reward = 6 + s.wave;
      if (s.wave % 3 === 0 && s.toSpawn % 4 === 0) { sc.props.hp = hp * 3; sc.props.speed = speed * 0.7; sc.props.reward *= 3; sc.props.big = true; }
      if (s.toSpawn > 0) ctx.timer(Math.max(0.35, 0.9 - s.wave * 0.05), spawnOne);
    };
    spawnOne();
    this.drawHud(ctx);
  },
  gameOver(ctx) {
    const s = ctx.state;
    s.over = true;
    const h = hud(ctx);
    if (h) h.panel('over', 'The base has fallen', `You survived ${s.wave - 1} wave${s.wave - 1 === 1 ? '' : 's'}.\nRestarting in 6s`);
    ctx.timer(6, () => this.restart(ctx));
  },
  restart(ctx) {
    const s = ctx.state;
    const sync = ctx.net.hub.sync;
    for (const e of [...ctx.findAll('enemy'), ...ctx.findAll('tower'), ...ctx.findAll('shot')]) { if (sync) sync.despawn(e); else ctx.destroy(e); }
    s.gold = ctx.props.startGold;
    s.base = ctx.props.baseHealth;
    s.wave = 0;
    s.toSpawn = 0;
    s.over = false;
    s.cleared = false;
    s.nextWaveAt = ctx.time.elapsed + ctx.props.waveDelay;
    ctx.send('goldChanged', { gold: s.gold });
    const h = hud(ctx);
    if (h) h.remove('over');
    this.drawHud(ctx);
  },
  drawHud(ctx) {
    const h = hud(ctx);
    if (!h) return;
    const s = ctx.state;
    h.text('gold', `Gold ${s.gold}   Base ${s.base}/${ctx.props.baseHealth}`, { anchor: 'top-left' }).style.fontSize = '18px';
    const next = s.nextWaveAt !== undefined ? `next wave in ${Math.max(0, Math.ceil(s.nextWaveAt - ctx.time.elapsed))}s` : `${ctx.findAll('enemy').length + s.toSpawn} enemies`;
    h.text('wave', `Wave ${s.wave}   ${next}`, { anchor: 'top-right', y: 48 });
    h.text('hint', `Click / tap to build a tower (${ctx.props.towerCost} gold, shared) · not on the road`, { anchor: 'bottom-right' });
  },
});

// Fit the whole map into the canvas.
defineScript({
  name: 'MapCamera',
  description: 'Fits the camera zoom to the map.',
  props: { width: { type: 'number', default: 37 }, height: { type: 'number', default: 19 } },
  onUpdate(ctx) {
    const r = ctx.engine.renderer;
    if (!r) return;
    ctx.get('Camera2D').zoom = Math.min(r.width / (r.pixelsPerUnit * ctx.props.width), r.height / (r.pixelsPerUnit * ctx.props.height));
  },
});

// Homing projectile fired by towers. Local-only decoration on clients: the
// host decides damage.
defineScript({
  name: 'Shot',
  description: 'Homes in on its target and applies damage.',
  props: {
    speed: { type: 'number', default: 14, min: 1, max: 100 },
    damage: { type: 'integer', default: 1, min: 1 },
    target: { type: 'entity', default: 0 },
    lifetime: { type: 'number', default: 2 },
  },
  onStart(ctx) { ctx.state.age = 0; },
  onFixedUpdate(ctx, dt) {
    ctx.state.age += dt;
    const target = ctx.props.target;
    if (!target || !ctx.world.isAlive(target) || ctx.state.age > ctx.props.lifetime) { ctx.destroy(); return; }
    const t = ctx.transform;
    const tt = ctx.getOn(target, 'Transform');
    const dx = tt.x - t.x, dy = tt.y - t.y;
    const d = Math.hypot(dx, dy);
    const step = ctx.props.speed * dt;
    if (d <= Math.max(step, 0.3)) {
      ctx.sendTo(target, 'damage', { amount: ctx.props.damage });
      ctx.destroy();
      return;
    }
    t.setPosition(t.x + (dx / d) * step, t.y + (dy / d) * step);
  },
});

// Turret: aims at the nearest enemy in range and fires Shot prefabs.
defineScript({
  name: 'Tower',
  description: 'Auto-targeting turret.',
  props: {
    range: { type: 'number', default: 3.6, min: 0.5, max: 20 },
    fireInterval: { type: 'number', default: 0.65, min: 0.05, max: 5 },
    damage: { type: 'integer', default: 1, min: 1 },
    builtBy: { type: 'string', default: '' },
  },
  onStart(ctx) {
    ctx.state.cooldown = 0.3;
    for (const child of ctx.world.getChildren(ctx.entity)) {
      if (ctx.nameOf(child) === 'Range') { const s = ctx.getOn(child, 'Shape'); if (s) s.radius = ctx.props.range; }
    }
    const em = ctx.get('ParticleEmitter');
    if (em) em.burst(12);
  },
  onFixedUpdate(ctx, dt) {
    const s = ctx.state;
    s.cooldown -= dt;
    const t = ctx.transform;
    let best, bestD = ctx.props.range;
    for (const e of ctx.findAll('enemy')) {
      const et = ctx.getOn(e, 'Transform');
      const d = Math.hypot(et.x - t.x, et.y - t.y);
      if (d < bestD) { bestD = d; best = e; }
    }
    if (best === undefined) return;
    const et = ctx.getOn(best, 'Transform');
    const barrel = ctx.world.getChildren(ctx.entity).find((c) => ctx.nameOf(c) === 'Barrel');
    if (barrel !== undefined) ctx.getOn(barrel, 'Transform').angle = Math.atan2(et.y - t.y, et.x - t.x) - Math.PI / 2;
    if (s.cooldown > 0 || !ctx.net.isHost) return;
    s.cooldown = ctx.props.fireInterval;
    const shot = ctx.spawn('Shot', { position: { x: t.x, y: t.y + 0.3 } });
    const sp = ctx.getOn(shot, 'Script').props;
    sp.target = best;
    sp.damage = ctx.props.damage;
    ctx.audio.play('shoot', { volume: 0.25, pitchVariation: 0.1 });
  },
});
